<div class="security-grid"><section class="admin-panel"><div class="panel-head"><h3>Change Password</h3><span>Use a unique password of 8–12 characters.</span></div><form method="post" action="<?=url('portal/password')?>" class="admin-form"><?=csrf_field()?><label class="full"><span>Current Password</span><input type="password" name="current_password" required autocomplete="current-password"></label><label><span>New Password</span><input type="password" name="new_password" required minlength="8" maxlength="12" autocomplete="new-password"></label><label><span>Confirm New Password</span><input type="password" name="password_confirmation" required minlength="8" maxlength="12" autocomplete="new-password"></label><button class="admin-btn full">Update Password Securely</button></form></section><aside class="admin-panel security-info"><h3>Account Security</h3><ul><li>Passwords are hashed using Argon2id.</li><li>Login attempts are rate limited.</li><li>Sessions are regenerated after login.</li><li>Authorization is checked server-side.</li></ul></aside></div>
